const input = $input.first()?.json || {};

function text(value, fallback = '') {
  const result = String(value ?? '').replace(/\r\n/g, '\n').replace(/\r/g, '\n').trim();
  return result || fallback;
}
function parse(value, fallback = {}) {
  if (value && typeof value === 'object') return value;
  try { return JSON.parse(String(value || '')); } catch (error) { return fallback; }
}

const jobPayload = parse(input.payloadJson, {});
const resolutionContext = parse(input.resolutionContextJson || jobPayload.resolutionContextJson, {});
const explicitQuestion = parse(input.resolutionQuestionJson || jobPayload.resolutionQuestionJson, {});
const question = Object.keys(explicitQuestion).length
  ? explicitQuestion
  : (resolutionContext.resolutionQuestion && typeof resolutionContext.resolutionQuestion === 'object'
    ? resolutionContext.resolutionQuestion
    : resolutionContext);
const operationMode = text(input.operationMode || jobPayload.operationMode, 'enqueue_answer');
const allowedModes = new Set(['enqueue_answer', 'apply_person_resolution', 'finalize_memory_conflict']);
if (!allowedModes.has(operationMode)) throw new Error(`Unsupported resolution operationMode: ${operationMode}.`);

const questionId = text(input.resolutionQuestionId || jobPayload.resolutionQuestionId || question.questionId);
const questionType = text(input.resolutionQuestionType || jobPayload.resolutionQuestionType || question.questionType).toLowerCase();
if (!questionId || !['person_resolution', 'memory_conflict'].includes(questionType)) {
  throw new Error('Resolution apply input requires a supported questionId and questionType.');
}
if (operationMode === 'apply_person_resolution' && questionType !== 'person_resolution') {
  throw new Error('Person apply mode received a non-person question.');
}
if (operationMode === 'finalize_memory_conflict' && questionType !== 'memory_conflict') {
  throw new Error('Memory finalizer received a non-conflict question.');
}

const answerText = text(input.answerText || jobPayload.answerText || jobPayload.question || jobPayload.messageText);
const answerMessageId = text(input.answerMessageId || input.messageId || jobPayload.answerMessageId || jobPayload.messageId);
if (!answerText || !answerMessageId) throw new Error('Resolution apply input requires answerText and answerMessageId.');
const jobId = text(input.jobId || jobPayload.jobId);
if (operationMode !== 'enqueue_answer' && !jobId) {
  throw new Error('Resolution worker apply requires a durable jobId.');
}

return [{ json: {
  ...input,
  operationMode,
  resolutionQuestionId: questionId,
  resolutionQuestionType: questionType,
  resolutionQuestion: question,
  resolutionQuestionJson: JSON.stringify(question),
  resolutionQuestionRowInstanceId: text(input.resolutionQuestionRowInstanceId || jobPayload.resolutionQuestionRowInstanceId || question.rowInstanceId),
  resolutionContext,
  resolutionContextJson: JSON.stringify(resolutionContext),
  resolutionTargetPointId: text(input.resolutionTargetPointId || jobPayload.resolutionTargetPointId || question.qdrantQuestionPointId),
  answerText,
  // The durable queue's v1 payload schema carries the callback selection in
  // resolutionContextJson rather than as a top-level field.
  selectedRef: text(input.selectedRef || jobPayload.selectedRef || resolutionContext.selectedRef),
  answerMessageId,
  incomingAnswerMessageId: answerMessageId,
  messageId: answerMessageId,
  messageDateIso: text(input.messageDateIso || jobPayload.messageDateIso, new Date().toISOString()),
  jobId,
  telegramUserId: text(input.telegramUserId || jobPayload.telegramUserId || question.telegramUserId),
  chatId: text(input.chatId || jobPayload.chatId || question.chatId),
  userId: text(input.userId || jobPayload.userId || question.userId),
  memoryUserId: text(input.memoryUserId || jobPayload.memoryUserId || question.memoryUserId),
  tenantId: text(input.tenantId || jobPayload.tenantId || question.tenantId),
  memoryTenantId: text(input.memoryTenantId || jobPayload.memoryTenantId || question.memoryTenantId || question.tenantId),
  qdrantCollection: text(input.qdrantCollection || jobPayload.qdrantCollection || question.qdrantCollection),
  memoryCompileResult: parse(input.memoryCompileResultJson || input.memoryCompileResult || jobPayload.memoryCompileResultJson, {}),
  resolutionApplyVersion: 'chelsea_resolution_apply_v2_0'
} }];

const normalized = $('Code | Normalize Resolution Apply Input | InputModule').first().json || {};
const matchedRows = $input.all().map(item => item.json || {}).filter(item => String(item.questionId || '').trim());
if (matchedRows.length !== 1) throw new Error(`Resolution exact read cardinality is ${matchedRows.length}.`);
const row = matchedRows[0];

function text(value, fallback = '') {
  const result = String(value ?? '').replace(/\r\n/g, '\n').replace(/\r/g, '\n').trim();
  return result || fallback;
}
function normalizedAnswer(value) {
  return text(value).normalize('NFKC').replace(/\s+/g, ' ').toLocaleLowerCase('ru');
}
function time(value) {
  const parsed = Date.parse(text(value));
  return Number.isFinite(parsed) ? parsed : 0;
}

if (text(row.questionId) !== text(normalized.resolutionQuestionId)) {
  throw new Error('Resolution question exact read did not return the requested questionId.');
}
if (text(row.questionType).toLowerCase() !== text(normalized.resolutionQuestionType).toLowerCase()) {
  throw new Error('Resolution question type changed before apply.');
}
if (text(row.memoryTenantId || row.tenantId) !== text(normalized.memoryTenantId || normalized.tenantId)) {
  throw new Error('Resolution question tenant mismatch.');
}
if (text(row.tenantId) !== text(normalized.tenantId)
  || text(row.memoryTenantId) !== text(normalized.memoryTenantId)) {
  throw new Error('Resolution question tenant identity is not exact.');
}
if (text(row.qdrantCollection) !== text(normalized.qdrantCollection)) {
  throw new Error('Resolution question Qdrant collection mismatch.');
}
if (text(row.qdrantQuestionPointId) !== text(normalized.resolutionTargetPointId)) {
  throw new Error('Resolution question target Qdrant point mismatch.');
}
if (text(row.chatId) !== text(normalized.chatId)
  || text(row.telegramUserId) !== text(normalized.telegramUserId)) {
  throw new Error('Resolution question Telegram identity mismatch.');
}

const status = text(row.status).toLowerCase();
const terminal = new Set(['resolved', 'rejected', 'closed']);
const persistedAnswerMessageId = text(row.answerMessageId);
const persistedAnswerText = text(row.answerText);
const persistedSelectedRef = text(row.selectedRef);
const incomingAnswerMessageId = text(normalized.incomingAnswerMessageId || normalized.answerMessageId);
const incomingAnswerText = text(normalized.answerText);
const incomingSelectedRef = text(normalized.selectedRef);
const sameMessage = Boolean(persistedAnswerMessageId && persistedAnswerMessageId === incomingAnswerMessageId);
const sameSelectedOption = Boolean(persistedSelectedRef && persistedSelectedRef === incomingSelectedRef);
const sameAnswer = sameSelectedOption || Boolean(!persistedSelectedRef && !incomingSelectedRef
  && persistedAnswerText && normalizedAnswer(persistedAnswerText) === normalizedAnswer(incomingAnswerText));
const exactPersistedAnswer = sameMessage && sameAnswer;
const answerLeaseExpired = time(row.answerClaimLeaseUntil) <= Date.now();
const persistedJobId = text(row.jobId);
const lastAcceptedJobId = text(row.lastAcceptedJobId);
const lastAcceptedMessageId = text(row.lastAcceptedAnswerMessageId);
const lastAcceptedText = text(row.lastAcceptedAnswerText);
const lastAcceptedSelectedRef = text(row.lastAcceptedSelectedRef);
const samePreviouslyProcessedAnswer = status === 'pending'
  && lastAcceptedMessageId === incomingAnswerMessageId
  && (Boolean(lastAcceptedSelectedRef && lastAcceptedSelectedRef === incomingSelectedRef)
    || Boolean(!lastAcceptedSelectedRef && !incomingSelectedRef && lastAcceptedText
      && normalizedAnswer(lastAcceptedText) === normalizedAnswer(incomingAnswerText)));

let stateReady = false;
let claimMode = 'none';
let canonicalAnswerMessageId = incomingAnswerMessageId;
let canonicalAnswerText = incomingAnswerText;
let canonicalSelectedRef = incomingSelectedRef;

if (normalized.operationMode === 'enqueue_answer') {
  if (status === 'asked' || status === 'dispatching') {
    stateReady = true;
    claimMode = 'new';
  } else if (status === 'answer_claimed' && sameMessage && sameAnswer) {
    stateReady = true;
    claimMode = 'resume';
    canonicalAnswerMessageId = persistedAnswerMessageId;
    canonicalAnswerText = persistedAnswerText;
    canonicalSelectedRef = persistedSelectedRef;
  } else if (status === 'answer_claimed' && answerLeaseExpired && sameAnswer) {
    stateReady = true;
    claimMode = 'reclaim';
    canonicalAnswerMessageId = persistedAnswerMessageId;
    canonicalAnswerText = persistedAnswerText;
    canonicalSelectedRef = persistedSelectedRef;
  }
} else {
  const workerState = ['answer_claimed', 'answer_queued', 'applying'].includes(status);
  const jobMatches = !persistedJobId || persistedJobId === text(normalized.jobId);
  stateReady = workerState && exactPersistedAnswer && jobMatches;
  claimMode = stateReady ? 'durable_job_reconcile' : 'none';
  canonicalAnswerMessageId = persistedAnswerMessageId || incomingAnswerMessageId;
  canonicalAnswerText = persistedAnswerText || incomingAnswerText;
  canonicalSelectedRef = persistedSelectedRef || incomingSelectedRef;
}

const sameAcceptedAnswer = ['answer_queued', 'applying'].includes(status)
  && sameMessage && sameAnswer
  && (normalized.operationMode === 'enqueue_answer' || !persistedJobId || persistedJobId === text(normalized.jobId));
const sameCompletedClarificationAnswer = samePreviouslyProcessedAnswer
  && (normalized.operationMode === 'enqueue_answer'
    || (lastAcceptedJobId && lastAcceptedJobId === text(normalized.jobId)));
const terminalAccepted = terminal.has(status) && exactPersistedAnswer
  && (normalized.operationMode === 'enqueue_answer' || (persistedJobId && persistedJobId === text(normalized.jobId)));

if (!stateReady && !terminalAccepted && !sameCompletedClarificationAnswer
  && !(normalized.operationMode === 'enqueue_answer' && sameAcceptedAnswer)) {
  throw new Error(`Resolution question has invalid or non-recoverable state ${status || '<empty>'} for ${normalized.operationMode}.`);
}
if (normalized.operationMode === 'enqueue_answer') {
  if (text(row.telegramUserId) && text(row.telegramUserId) !== text(normalized.telegramUserId)) {
    throw new Error('Resolution answer user does not match the asked question.');
  }
  if (text(row.chatId) && text(row.chatId) !== text(normalized.chatId)) {
    throw new Error('Resolution answer chat does not match the asked question.');
  }
}

return [{ json: {
  ...normalized,
  answerMessageId: canonicalAnswerMessageId,
  messageId: canonicalAnswerMessageId,
  answerText: canonicalAnswerText,
  selectedRef: canonicalSelectedRef,
  incomingAnswerMessageId,
  resolutionQuestion: row,
  resolutionQuestionJson: JSON.stringify(row),
  resolutionQuestionStatus: status,
  resolutionQuestionJobId: persistedJobId || (sameCompletedClarificationAnswer ? lastAcceptedJobId : ''),
  resolutionQuestionRowInstanceId: text(row.rowInstanceId),
  resolutionAlreadyTerminal: terminalAccepted
    || sameCompletedClarificationAnswer
    || (normalized.operationMode === 'enqueue_answer' && sameAcceptedAnswer),
  resolutionAnswerAlreadyClaimed: status === 'answer_claimed' && sameMessage && sameAnswer,
  resolutionAnswerAlreadyAccepted: sameAcceptedAnswer,
  resolutionAnswerAlreadyClarified: sameCompletedClarificationAnswer,
  resolutionAnswerClaimRequired: normalized.operationMode === 'enqueue_answer' && stateReady,
  resolutionAnswerClaimMode: claimMode,
  resolutionAnswerLeaseExpired: answerLeaseExpired,
  previousAnswerMessageId: persistedAnswerMessageId,
  previousAnswerClaimLeaseOwner: text(row.answerClaimLeaseOwner),
  previousAnswerClaimLeaseUntil: text(row.answerClaimLeaseUntil),
  previousAnswerAttemptCount: Number(row.answerAttemptCount || 0),
  previousAnswerIdempotencyKey: text(row.answerIdempotencyKey),
  resolutionStateReady: stateReady,
  resolutionStateVersion: 'chelsea_resolution_state_v2_1'
} }];

const state = $input.first()?.json || {};
const row = state.resolutionQuestion || {};

function text(value, fallback = '') {
  const result = String(value ?? '').replace(/\r\n/g, '\n').replace(/\r/g, '\n').trim();
  return result || fallback;
}

if (state.operationMode !== 'enqueue_answer' || state.resolutionAnswerClaimRequired !== true) {
  throw new Error('Resolution answer claim requires a recoverable enqueue_answer state.');
}
const memoryTenantId = text(state.memoryTenantId || state.tenantId);
const questionId = text(state.resolutionQuestionId);
const answerMessageId = text(state.answerMessageId);
let answerText = text(state.answerText);
if (text(row.questionType) === 'memory_conflict') {
  if (text(state.selectedRef) === 'keep_existing') {
    answerText = `Сейчас верно прежнее значение: ${text(row.existingValue)}.`;
  } else if (text(state.selectedRef) === 'accept_incoming') {
    answerText = `Сейчас верно новое значение: ${text(row.incomingValue)}.`;
  }
}
if (!memoryTenantId || !questionId || !answerMessageId || !answerText) {
  throw new Error('Resolution answer claim identity is incomplete.');
}

const now = new Date();
const answerIdempotencyKey = `resolution:${memoryTenantId}:${questionId}:${answerMessageId}`;
const priorKey = text(row.answerIdempotencyKey);
if (priorKey && priorKey !== answerIdempotencyKey) {
  throw new Error('Resolution answer idempotency identity changed during reclaim.');
}

return [{ json: {
  ...state,
  answerText,
  previousResolutionQuestionStatus: text(row.status),
  previousAnswerMessageId: text(row.answerMessageId),
  previousAnswerIdempotencyKey: priorKey,
  previousAnswerClaimLeaseOwner: text(row.answerClaimLeaseOwner),
  previousAnswerClaimLeaseUntil: text(row.answerClaimLeaseUntil),
  previousAnswerAttemptCount: Number(row.answerAttemptCount || 0),
  answerIdempotencyKey,
  answerClaimLeaseOwner: `answer:${String($workflow.id)}:${String($execution.id)}`,
  answerClaimLeaseUntil: new Date(now.getTime() + 12 * 60 * 1000).toISOString(),
  answerAttemptCount: Number(row.answerAttemptCount || 0) + 1,
  lastAnswerAttemptMessageId: text(state.incomingAnswerMessageId || state.answerMessageId),
  answeredAt: text(row.answeredAt || state.messageDateIso, now.toISOString()),
  stateChangedAt: now.toISOString(),
  answerClaimReady: true,
  answerClaimVersion: 'chelsea_resolution_answer_claim_v2_1'
} }];

const expected = $('Code | Build Resolution Answer Claim | EnqueueResolution').first().json || {};
const matchedRows = $input.all().map(item => item.json || {}).filter(item => String(item.questionId || '').trim());
if (matchedRows.length !== 1) throw new Error(`Resolution answer claim read-back cardinality is ${matchedRows.length}.`);
const row = matchedRows[0];
function text(value) { return String(value ?? '').trim(); }

if (text(row.questionId) !== text(expected.resolutionQuestionId)) throw new Error('Resolution answer claim questionId mismatch.');
if (text(row.memoryTenantId || row.tenantId) !== text(expected.memoryTenantId || expected.tenantId)) throw new Error('Resolution answer claim tenant mismatch.');
if (text(row.rowInstanceId) !== text(expected.resolutionQuestionRowInstanceId)) throw new Error('Resolution answer claim rowInstanceId mismatch.');
if (text(row.status) !== 'answer_claimed') throw new Error('Resolution answer claim status was not persisted.');
for (const field of [
  'answerMessageId', 'answerText', 'selectedRef', 'answerIdempotencyKey',
  'answerClaimLeaseOwner', 'answerClaimLeaseUntil', 'lastAnswerAttemptMessageId'
]) {
  if (text(row[field]) !== text(expected[field])) throw new Error(`Resolution answer claim ${field} mismatch.`);
}
if (Number(row.answerAttemptCount || 0) !== Number(expected.answerAttemptCount || 0)) {
  throw new Error('Resolution answer claim attempt count mismatch.');
}
return [{ json: {
  ...expected,
  resolutionQuestion: row,
  resolutionQuestionJson: JSON.stringify(row),
  resolutionAnswerClaimVerified: true
} }];

const source = $input.first()?.json || {};
const row = source.resolutionQuestion || {};

function text(value, fallback = '') { const result = String(value ?? '').trim(); return result || fallback; }
function parse(value, fallback) { try { return typeof value === 'object' ? value : JSON.parse(String(value || '')); } catch (error) { return fallback; } }
function hash(value) {
  const sourceText = String(value ?? '').normalize('NFKC');
  let a = 0x811c9dc5; let b = 0x9e3779b9;
  for (let index = 0; index < sourceText.length; index += 1) {
    const code = sourceText.charCodeAt(index);
    a = Math.imul((a ^ code) >>> 0, 0x01000193) >>> 0;
    b = Math.imul((b ^ (code + index)) >>> 0, 0x85ebca6b) >>> 0;
  }
  return a.toString(16).padStart(8, '0') + b.toString(16).padStart(8, '0');
}

if (source.operationMode !== 'enqueue_answer' || source.resolutionStateReady !== true) {
  throw new Error('Durable resolution job can be built only from an exact asked question.');
}

const questionType = text(row.questionType);
const jobKind = questionType === 'memory_conflict' ? 'memory_conflict_resolution' : 'person_resolution';
const memoryTenantId = text(row.memoryTenantId || source.memoryTenantId || row.tenantId);
const questionId = text(row.questionId);
const answerMessageId = text(source.answerMessageId);
const idempotencyKey = `resolution:${memoryTenantId}:${questionId}:${answerMessageId}`;
const jobId = `memory_job_${hash(idempotencyKey)}`;
const effectiveAnswer = text(source.answerText);
const stableMessageDateIso = text(row.answeredAt || source.answeredAt || source.messageDateIso || row.sourceMessageDateIso);
if (!stableMessageDateIso || !Number.isFinite(Date.parse(stableMessageDateIso))) {
  throw new Error('Durable resolution job requires a stable message timestamp.');
}

// Keep only immutable question data and the exact claimed answer. Lease owners,
// attempt counters and lifecycle statuses change during a reclaim and must never
// change the durable queue payload hash for the same answer idempotency key.
const stableQuestion = {
  questionRowKey: text(row.questionRowKey),
  rowInstanceId: text(row.rowInstanceId),
  questionId,
  tenantId: text(row.tenantId),
  memoryTenantId: text(row.memoryTenantId || row.tenantId),
  userId: text(row.userId),
  memoryUserId: text(row.memoryUserId || row.userId),
  telegramUserId: text(row.telegramUserId),
  chatId: text(row.chatId),
  sourceMessageId: text(row.sourceMessageId),
  sourceMessageDateIso: text(row.sourceMessageDateIso),
  uploadId: text(row.uploadId),
  sourceTitle: text(row.sourceTitle),
  qdrantCollection: text(row.qdrantCollection),
  questionType,
  priority: Number(row.priority || 0),
  questionText: text(row.questionText),
  mention: text(row.mention),
  subjectName: text(row.subjectName),
  relatedKnowledgeId: text(row.relatedKnowledgeId),
  relatedKnowledgeTitle: text(row.relatedKnowledgeTitle),
  qdrantQuestionPointId: text(row.qdrantQuestionPointId),
  stableKnowledgeId: text(row.stableKnowledgeId),
  stableQdrantPointId: text(row.stableQdrantPointId),
  existingValue: text(row.existingValue),
  incomingValue: text(row.incomingValue),
  plausibleHeadRefsJson: JSON.stringify(parse(row.plausibleHeadRefsJson, [])),
  candidatesJson: JSON.stringify(parse(row.candidatesJson, [])),
  candidateRefsJson: JSON.stringify(parse(row.candidateRefsJson, [])),
  allowCreateNewPerson: row.allowCreateNewPerson !== false,
  provisionalPersonId: text(row.provisionalPersonId),
  resolutionReason: text(row.resolutionReason),
  confidence: Number(row.confidence || 0),
  resolutionPolicy: text(row.resolutionPolicy),
  callbackQuestionKey: text(row.callbackQuestionKey),
  questionToken: text(row.questionToken),
  callbackOptionsJson: JSON.stringify(parse(row.callbackOptionsJson, [])),
  telegramQuestionMessageId: text(row.telegramQuestionMessageId),
  askedAt: text(row.askedAt),
  askedExpiresAt: text(row.askedExpiresAt),
  answerMessageId,
  answerText: effectiveAnswer,
  selectedRef: text(source.selectedRef),
  answeredAt: text(row.answeredAt || stableMessageDateIso),
  answerIdempotencyKey: text(row.answerIdempotencyKey || source.answerIdempotencyKey),
  contextJson: JSON.stringify(parse(row.contextJson, {})),
  queueSchemaVersion: text(row.queueSchemaVersion)
};

const targetContext = {
  resolutionQuestion: stableQuestion,
  questionId,
  questionType,
  qdrantQuestionPointId: text(row.qdrantQuestionPointId),
  qdrantCollection: text(row.qdrantCollection),
  stableKnowledgeId: text(row.stableKnowledgeId || row.relatedKnowledgeId),
  stableQdrantPointId: text(row.stableQdrantPointId),
  existingValue: text(row.existingValue),
  incomingValue: text(row.incomingValue),
  plausibleHeadRefs: parse(row.plausibleHeadRefsJson, []),
  provisionalPersonId: text(row.provisionalPersonId),
  candidates: parse(row.candidatesJson, []),
  selectedRef: text(source.selectedRef)
};
const payload = {
  jobId,
  jobKind,
  operationMode: jobKind === 'person_resolution' ? 'apply_person_resolution' : 'memory_conflict_resolution',
  resolutionQuestionId: questionId,
  resolutionQuestionRowInstanceId: text(row.rowInstanceId),
  resolutionQuestionType: questionType,
  resolutionTargetPointId: text(row.qdrantQuestionPointId),
  resolutionQuestionJson: JSON.stringify(stableQuestion),
  resolutionContextJson: JSON.stringify(targetContext),
  resolutionTargetContext: targetContext,
  answerText: effectiveAnswer,
  selectedRef: text(source.selectedRef),
  answerMessageId,
  answerIdempotencyKey: text(row.answerIdempotencyKey || source.answerIdempotencyKey),
  question: effectiveAnswer,
  messageText: effectiveAnswer,
  precedingAssistantQuestion: text(row.questionText),
  messageId: answerMessageId,
  messageDateIso: stableMessageDateIso,
  telegramUserId: text(source.telegramUserId || row.telegramUserId),
  chatId: text(source.chatId || row.chatId),
  userId: text(source.userId || row.userId),
  memoryUserId: text(source.memoryUserId || row.memoryUserId),
  tenantId: text(source.tenantId || row.tenantId),
  memoryTenantId,
  qdrantCollection: text(source.qdrantCollection || row.qdrantCollection),
  messageAuthorship: 'user_authored',
  source: 'telegram_resolution_reply',
  sourceType: 'telegram_resolution_reply',
  memoryWriteAllowed: jobKind === 'memory_conflict_resolution',
  universalMemoryEnabled: jobKind === 'memory_conflict_resolution'
};
const payloadJson = JSON.stringify(payload);
const payloadHash = hash(payloadJson);

return [{ json: {
  ...source,
  ...payload,
  jobId,
  idempotencyKey,
  payloadHash,
  payloadJson,
  jobKind,
  status: 'queued',
  attemptCount: 0,
  availableAt: new Date().toISOString(),
  leaseOwner: '',
  leaseUntil: '',
  lastErrorCode: '',
  lastErrorMessage: '',
  auditJson: '',
  resultJson: '',
  finishedAt: '',
  queueSchemaVersion: 'chelsea_memory_jobs_v1_0',
  durableResolutionJobReady: true
} }];

const job = $('Code | Build Durable Resolution Job | EnqueueResolution').first().json || {};
const response = $input.first()?.json || {};
function text(value, fallback = '') { const result = String(value ?? '').trim(); return result || fallback; }

const returnedJobId = text(response.jobId || response.queuedJobId || response.existingJobId);
const status = text(response.status || response.queueStatus).toLowerCase();
const enqueueOutcome = text(response.enqueueOutcome).toLowerCase();
const existingStatus = text(response.existingStatus).toLowerCase();
const acceptedStatus = new Set(['queued', 'existing', 'already_queued', 'done', 'accepted']);
const acceptedDuplicateStatus = new Set(['queued', 'retry', 'processing', 'completed']);
const acceptedDuplicate = enqueueOutcome === 'idempotent_duplicate'
  && acceptedDuplicateStatus.has(existingStatus);
const accepted = Boolean(returnedJobId)
  && (response.durableMemoryEnqueueVerified === true || acceptedStatus.has(status) || acceptedDuplicate);
if (!accepted) throw new Error('Durable memory queue did not confirm a validated resolution jobId.');

return [{ json: {
  ...job,
  jobId: returnedJobId,
  queueResponseStatus: status || existingStatus || 'confirmed',
  queueEnqueueOutcome: enqueueOutcome || 'confirmed',
  resolutionQuestionStatus: 'answer_queued',
  answerQueuedAt: new Date().toISOString(),
  durableResolutionEnqueueVerified: true
} }];

const expected = $('Code | Verify Durable Resolution Enqueue | EnqueueResolution').first().json || {};
const matchedRows = $input.all().map(item => item.json || {}).filter(item => String(item.questionId || '').trim());
if (matchedRows.length !== 1) throw new Error(`Queued resolution read-back cardinality is ${matchedRows.length}.`);
const row = matchedRows[0];
function text(value) { return String(value ?? '').trim(); }

if (text(row.questionId) !== text(expected.resolutionQuestionId)) throw new Error('Queued resolution questionId mismatch.');
if (text(row.memoryTenantId || row.tenantId) !== text(expected.memoryTenantId || expected.tenantId)) throw new Error('Queued resolution tenant mismatch.');
if (text(row.rowInstanceId) !== text(expected.resolutionQuestionRowInstanceId)) throw new Error('Queued resolution rowInstanceId mismatch.');
const status = text(row.status).toLowerCase();
const acceptedStatuses = new Set(['answer_queued', 'applying', 'resolved', 'rejected', 'closed', 'pending']);
if (!acceptedStatuses.has(status)) throw new Error(`Resolution answer queue advanced to unsupported state ${status || '<empty>'}.`);
const persisted = status === 'pending'
  ? {
      jobId: row.lastAcceptedJobId,
      answerMessageId: row.lastAcceptedAnswerMessageId,
      answerText: row.lastAcceptedAnswerText,
      selectedRef: row.lastAcceptedSelectedRef,
      answerIdempotencyKey: row.lastAcceptedAnswerIdempotencyKey
    }
  : row;
for (const field of ['jobId', 'answerMessageId', 'answerText', 'selectedRef', 'answerIdempotencyKey']) {
  if (text(persisted[field]) !== text(expected[field])) throw new Error(`Queued resolution ${field} mismatch.`);
}
if (status !== 'pending' && (text(row.answerClaimLeaseOwner) || text(row.answerClaimLeaseUntil))) {
  throw new Error('Queued resolution answer lease was not released.');
}
return [{ json: {
  ...row,
  jobId: text(persisted.jobId),
  answerMessageId: text(persisted.answerMessageId),
  answerText: text(persisted.answerText),
  selectedRef: text(persisted.selectedRef),
  answerIdempotencyKey: text(persisted.answerIdempotencyKey),
  resolutionQuestionId: text(row.questionId),
  resolutionQuestionStatus: status,
  durableResolutionAnswerQueuedVerified: true,
  durableResolutionAnswerQueuedVersion: 'chelsea_resolution_answer_queued_v2_1'
